// Blink an LED on pin 13 (the L LED blinks along)
// R1 = {{p:ohms}} ohms: LED current = (5 V - 2 V) / R1, and an R4 pin allows 8 mA
const int LED_PIN = 13;           // the L LED is on pin 13 too
const int WAIT_MS = {{p:wait}};

void setup() {
  pinMode(LED_PIN, OUTPUT);       // pin 13 drives the LED
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  delay(WAIT_MS);
  digitalWrite(LED_PIN, LOW);
  delay(WAIT_MS);
}

